focus_market = "US"
# @param {"type": "slider", "min": 1, "max": 5, "step": 1, "default": 1, "label": "Min quantity"}
min_qty = 1
# @param {"type": "slider", "min": 50, "max": 2000, "step": 50, "default": 500, "label": "Row cap"}
row_cap = 500
print(f"market='{focus_market}'  min_qty={min_qty}  row_cap={row_cap}")

-- Athena orders for one market, filtered + capped by scalar params.
-- '{focus_market}' is a STRING param (note the user-supplied quotes);
-- {min_qty} and {row_cap} are NUMERIC params.
SELECT order_id, user_id, product_id, quantity, unit_price, total, order_date, payment_method
FROM microvm_demo_db.orders
WHERE shipping_country = '{focus_market}'
  AND quantity >= {min_qty}
ORDER BY total DESC
LIMIT {row_cap}

